define({"topics":[{"title":"Calibrating RF Amplifier and UPM","shortdesc":"<p class=\"shortdesc\">Calibrate the maximum power for the RF amplifier. Also, calibrate and check the Universal Power Monitor (UPM) for each channel.<\/p>","href":"t_CalibratingRFAmplifierAndUPM.html","attributes":{"data-id":"id_2002056"},"menu":{"hasChildren":true},"tocID":"id_2002056-d46e5059","next":"id_2002056-d46e5059"},{"title":"Body coil tuning","shortdesc":"<p class=\"shortdesc\">Information on how to access instructions for tuning a body coil in the field using the RF Field Tuning Kit.<\/p>","href":"c_Body-Coil-Tuning_14626174.html","attributes":{"data-id":"id_13106174"},"menu":{"hasChildren":false},"tocID":"id_13106174-d46e7657","topics":[]},{"title":"Calibrating transmit\/receive dynamic disable","shortdesc":"<p class=\"shortdesc\">Calibrates the open circuit fault detection levels of the dynamic disable drivers in the driver module. Do this procedure after system installation, driver module replacement, body coil replacement, body hybrid replacement, or replacement of cabling between any of the previously listed devices.<\/p>","href":"t_CalibratingTRDynamicDisableParent.html","attributes":{"data-id":"id_2003808"},"menu":{"hasChildren":true},"tocID":"id_2003808-d46e7763","next":"id_2003808-d46e7763"}]});